<?php require_once 'includes/auth.php'; require_once 'includes/functions.php'; $user=require_login(); $stmt=db()->prepare('SELECT * FROM reservas WHERE user_id=? ORDER BY created_at DESC');$stmt->execute([$user['id']]);$reservas=$stmt->fetchAll();$title='Dashboard';require 'includes/header.php'; ?><section class="page"><h1>Dashboard</h1><p>Hola, <?= e($user['name']) ?>.</p><div class="dashboard-card"><h2>Mis reservas</h2><?php if(!$reservas): ?><p>Aún no tienes reservas.</p><?php else: ?><table class="table"><tr><th>Código</th><th>Fecha</th><th>Cajas</th><th>Estado</th></tr><?php foreach($reservas as $r): ?><tr><td><?=e($r['code'])?></td><td><?=e($r['delivery_date'])?></td><td><?=e((string)$r['quantity'])?></td><td><?=e($r['status'])?></td></tr><?php endforeach; ?></table><?php endif; ?></div></section><?php require 'includes/footer.php'; ?>
